'use client';
// Create an issue in any project the person can access, by hand or generated by AI from an idea.
import { useEffect, useState } from 'react';
import { type Any, api, toast, closeModal, openModal, pullRemote, can, aiBody } from '../core';
import { Modal } from '../ui';
import { TF, SF, TA, opts, MenuItem } from '../fields';
import { listProjects, getProject } from '../api/projects';

const TYPE_LIST = ['Story', 'Task', 'Bug', 'Spike'];
const err = { color: 'var(--danger)', fontSize: 12 } as const;

export function CreateIssueForm() {
  const [projects, setProjects] = useState<Any[]>([]);
  const [pid, setPid] = useState('');
  const [statuses, setStatuses] = useState<string[]>([]);
  const [f, setF] = useState({ title: '', description: '', type: '', status: '' });
  const [idea, setIdea] = useState('');
  const [files, setFiles] = useState<File[]>([]);
  const [busy, setBusy] = useState(false);
  const [ai, setAi] = useState(false);
  const [tried, setTried] = useState(false);
  const [error, setError] = useState('');
  const set = (k: string) => (e: Any) => setF((x) => ({ ...x, [k]: e.target.value }));

  useEffect(() => {
    listProjects()
      .then((r) => setProjects(Array.isArray(r) ? r : r?.projects || []))
      .catch((e) => toast(e.message, 'err'));
  }, []);
  useEffect(() => {
    if (!pid) return;
    getProject(pid)
      .then((r) => {
        const names = (r?.workflow || r?.project?.workflow || []).map((s: Any) => s.name);
        setStatuses(names);
        setF((x) => ({ ...x, status: names.includes(x.status) ? x.status : names[0] || '' }));
      })
      .catch((e) => toast(e.message, 'err'));
  }, [pid]);

  const generate = async () => {
    if (!idea.trim()) return toast('Write a one-line idea first.', 'err');
    setAi(true);
    try {
      const res = await api('/api/ai/new-ticket', {
        method: 'POST',
        body: aiBody({ idea: idea.trim(), projectId: pid }),
      });
      const t = res?.ticket || {};
      const type = TYPE_LIST.includes(t.type) ? t.type : 'Story';
      setF((x) => ({
        title: String(t.title || x.title),
        description: String(t.description || t.userStory || x.description),
        type,
        status: statuses.includes(t.status) ? t.status : x.status || statuses[0] || '',
      }));
    } catch (e: Any) {
      toast(e.message, 'err');
    } finally {
      setAi(false);
    }
  };

  const create = async () => {
    setTried(true);
    if (!pid || !f.title.trim() || !f.type) return;
    setBusy(true);
    setError('');
    try {
      const ids: string[] = [];
      for (const file of files) {
        const form = new FormData();
        form.set('file', file);
        form.set('purpose', 'attachment');
        const r = await fetch(`/api/projects/${encodeURIComponent(pid)}/files`, {
          method: 'POST',
          body: form,
        });
        const j = await r.json().catch(() => ({}));
        if (!r.ok) throw new Error(j.error || `Couldn’t attach ${file.name}`);
        ids.push(j.id);
      }
      const res = await api(`/api/projects/${encodeURIComponent(pid)}/issues`, {
        method: 'POST',
        body: { ...f, attachments: ids },
      });
      toast(`Created ${res?.issue?.key || 'issue'}`);
      closeModal();
      pullRemote?.({ quiet: true });
    } catch (e: Any) {
      setError(e.message || 'Couldn’t create the issue.');
      toast(e.message, 'err');
    } finally {
      setBusy(false);
    }
  };

  return (
    <Modal
      title="Create issue"
      actions={[
        { label: 'Cancel' },
        {
          label: ai ? 'Generating…' : 'Generate with AI',
          kind: 'ai',
          onClick: generate,
          disabled: ai || !pid || !can('ai.use'),
          keepOpen: true,
        } as Any,
        {
          label: busy ? 'Creating…' : 'Create',
          kind: 'primary',
          onClick: create,
          disabled: busy || ai,
          keepOpen: true,
        } as Any,
      ]}
    >
      <label className="field">
        <span>
          Project <span className="req">*</span>
        </span>
        <SF value={pid} onChange={(e: Any) => setPid(e.target.value)}>
          <MenuItem value="">Select a project</MenuItem>
          {projects.map((p: Any) => (
            <MenuItem key={p.id} value={p.id}>
              {p.name} ({p.key})
            </MenuItem>
          ))}
        </SF>
        {tried && !pid && <span style={err}>Pick a project.</span>}
      </label>
      {pid && (
        <>
          <label className="field">
            <span>Idea (one line)</span>
            <TF
              value={idea}
              onChange={(e: Any) => setIdea(e.target.value)}
              placeholder="e.g. Customers can export their order history as a PDF"
            />
            {ai && <span className="muted small">AI is writing the issue…</span>}
          </label>
          <label className="field">
            <span>
              Title <span className="req">*</span>
            </span>
            <TF value={f.title} onChange={set('title')} />
            {tried && !f.title.trim() && <span style={err}>Title is required.</span>}
          </label>
          <label className="field">
            <span>Description</span>
            <TA style={{ minHeight: 100 }} value={f.description} onChange={set('description')} />
          </label>
          <div className="grid2">
            <label className="field">
              <span>
                Type <span className="req">*</span>
              </span>
              <SF value={f.type} onChange={set('type')}>
                <MenuItem value="">Select a type</MenuItem>
                {opts(TYPE_LIST)}
              </SF>
              {tried && !f.type && <span style={err}>Choose a type.</span>}
            </label>
            <label className="field">
              <span>Status</span>
              <SF value={f.status} onChange={set('status')}>
                {opts(statuses)}
              </SF>
            </label>
          </div>
          <label className="field">
            <span>Attachments</span>
            <input
              type="file"
              multiple
              onChange={(e) => setFiles(Array.from(e.target.files || []))}
            />
          </label>
        </>
      )}
      {error && (
        <p role="alert" style={err}>
          {error}
        </p>
      )}
    </Modal>
  );
}

export function openCreateIssueForm() {
  if (!can('issue.create')) return;
  openModal(<CreateIssueForm />);
}
